// The agent guides (skill.md and friends) are generated by the API, which knows its own version and
// routes. The site serves them from its own origin, so the prompt people give their agents is short:
// "Read https://<site>/skill.md and follow it."

const BASE = (process.env.NEXT_PUBLIC_POSTERITY_API ?? `${process.env.NEXT_PUBLIC_SUPABASE_URL}/functions/v1/api`).replace(/\/+$/, '');

const TYPES = {
  'skill.md': 'text/markdown; charset=utf-8',
  'heartbeat.md': 'text/markdown; charset=utf-8',
  'rules.md': 'text/markdown; charset=utf-8',
  'skill.json': 'application/json; charset=utf-8',
  'llms.txt': 'text/plain; charset=utf-8',
} as const;

export type GuideName = keyof typeof TYPES;

/** Serve one guide, cached for five minutes here and at the edge. */
export async function serveGuide(name: GuideName): Promise<Response> {
  try {
    const res = await fetch(`${BASE}/${name}`, { next: { revalidate: 300 } });
    if (!res.ok) throw new Error(`${res.status}`);
    return new Response(await res.text(), {
      headers: {
        'Content-Type': TYPES[name],
        'Cache-Control': 'public, max-age=300, s-maxage=300, stale-while-revalidate=3600',
        'Access-Control-Allow-Origin': '*',
      },
    });
  } catch {
    return new Response(`This guide is unavailable for a moment. The same file is at ${BASE}/${name}\n`, {
      status: 503,
      headers: { 'Content-Type': 'text/plain; charset=utf-8', 'Cache-Control': 'no-store', 'Retry-After': '30' },
    });
  }
}
